from pathlib import Path
import re
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it']
ips={}
for i in range(1,41):
    s=Path(f'pc{i}.startup').read_text()
    ips[i]=re.search(r'inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24',s).group(1)
assert ips[32]=='10.15.8.14'
parents={}
for z in zones[1:]:
    parts=z.split('.')
    p='.'.join(parts[1:]) if len(parts)>1 else '.'
    assert p in zones
    parents[z]=p
assert len(parents)==30

def ns(z): return 'ns.root.' if z=='.' else 'ns.'+z+'.'
for i,z in enumerate(zones,1):
    d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
    (d/'named.conf').write_text('options {\\n    directory \"/var/cache/bind\";\\n    listen-on { any; };\\n    listen-on-v6 { none; };\\n    recursion no;\\n    allow-query { any; };\\n    dnssec-validation no;\\n};\\nzone \"'+z+'\" { type master; file \"/etc/bind/db.lab\"; };\\n')
    lines=['"'$TTL 300'"',f'@ IN SOA {ns(z)} hostmaster.{\"\" if z==\".\" else z+\".\"} ( 1 3600 600 86400 300 )',f'@ IN NS {ns(z)}',f'{ns(z)} IN A {ips[i]}']
    if i>=16: lines.append(f'@ IN A {ips[i]}')
    if z=='example.com': lines.append(f'www IN A {ips[i]}')
    if z in ('company.com','university.edu'):
        lines += [f'@ IN MX 10 mail.{z}.',f'mail IN A {ips[i]}']
    for child,p in parents.items():
        if p==z:
            ci=zones.index(child)+1
            lines += [f'{child}. IN NS {ns(child)}',f'{ns(child)} IN A {ips[ci]}']
    (d/'db.lab').write_text('\\n'.join(lines)+'\\n')
d=Path('pc32/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf').write_text('''options {
    directory \"/var/cache/bind\";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { 10.15.0.0/16; 127.0.0.1; };
    allow-query-cache { 10.15.0.0/16; 127.0.0.1; };
    dnssec-validation no;
    empty-zones-enable no;
};
zone \".\" { type hint; file \"/etc/bind/db.root.lab\"; };
''')
(d/'db.root.lab').write_text(f'. 300 IN NS {ns(\".\")}\\n{ns(\".\")} 300 IN A {ips[1]}\\n')
for device in [*(f'pc{i}' for i in range(1,41)),*(f'r{i}' for i in range(1,9))]:
    p=Path(device+'.startup'); s=p.read_text(); s+='\\n# DNS resolver for the laboratory.\\nprintf \"nameserver 10.15.8.14\\\\n\" > /etc/resolv.conf\\n'
    if device.startswith('pc') and int(device[2:])<=32:
        s+='systemctl restart bind9\\n'
    p.write_text(s)
print('Generated 31 zones and 30 delegations; resolver:',ips[32])
PY"

